<?php
declare(strict_types=1);
$autoload = dirname(__DIR__) . '/vendor/autoload.php';
if (is_file($autoload)) require $autoload;
require dirname(__DIR__) . '/src/bootstrap.php';

use App\Core\Env;
use App\Core\Security;
use App\Core\LocalState;
use App\Core\Database;
use App\Repositories\InsightRepository;

Security::requireAuth();
$env = new Env(dirname(__DIR__) . '/.env');
$localState = new LocalState();
$appState = $localState->all();
$environment = htmlspecialchars($env->get('APP_ENV', 'not configured'), ENT_QUOTES, 'UTF-8');
header('X-Frame-Options: SAMEORIGIN');
header('X-Content-Type-Options: nosniff');
header('Referrer-Policy: strict-origin-when-cross-origin');

$range = in_array((string)($appState['settings']['date_range'] ?? '7'), ['7','30','90'], true) ? (int)$appState['settings']['date_range'] : 7;
$from = date('Y-m-d', strtotime('-' . ($range - 1) . ' days'));
$to = date('Y-m-d');
$summary = ['spend' => 0, 'conversions' => 0, 'revenue' => 0, 'cpa' => 0, 'roas' => 0];
$campaigns = [];
$dailyTotals = [];
$dbError = null;
try {
    $repo = new InsightRepository((new Database($env))->pdo());
    $summary = $repo->summary($from, $to);
    $campaigns = $repo->topCampaigns($from, $to);
    $dailyTotals = $repo->dailyTotals($from, $to);
} catch (Throwable $e) { $dbError = $e->getMessage(); }
$hasLiveData = (float)$summary['spend'] > 0 || (float)$summary['conversions'] > 0 || (float)$summary['revenue'] > 0;
$demo = $env->get('APP_ENV', 'production') !== 'production' && filter_var($env->get('DEMO_MODE', '0'), FILTER_VALIDATE_BOOL);
if ($demo && $dbError !== null) {
    $summary = ['spend' => $appState['demo']['spend'], 'conversions' => $appState['demo']['conversions'], 'revenue' => $appState['demo']['revenue'], 'cpa' => $appState['demo']['spend'] / max(1, $appState['demo']['conversions']), 'roas' => $appState['demo']['revenue'] / max(1, $appState['demo']['spend'])];
}
$systemStatus = $dbError !== null ? 'Database unavailable' : ($hasLiveData ? 'Live data connected' : 'Awaiting first sync');
$currency = htmlspecialchars((string)($appState['settings']['currency'] ?? $env->get('DEFAULT_CURRENCY', 'USD')), ENT_QUOTES, 'UTF-8');
$brandName = htmlspecialchars((string)($appState['brand']['name'] ?? 'Stratmark Adpilot'), ENT_QUOTES, 'UTF-8');
$logoUrl = !empty($appState['brand']['logo']) ? '/media.php?v=' . rawurlencode((string)($appState['updated_at'] ?? '1')) : null;
$spend = number_format((float)$summary['spend'], 2);
$conversions = number_format((float)$summary['conversions'], 0);
$cpa = number_format((float)$summary['cpa'], 2);
$roas = number_format((float)$summary['roas'], 2);
$rangeLabel = $range === 7 ? 'Last 7 days' : ($range === 30 ? 'Last 30 days' : 'Last 90 days');
$esc = static fn(string $value): string => htmlspecialchars($value, ENT_QUOTES, 'UTF-8');
$chartMax = 0.0; foreach ($dailyTotals as $row) $chartMax = max($chartMax, (float)$row['spend']);
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Stratmark Adpilot — Overview</title><style>
:root{--navy:#12243a;--ink:#172231;--muted:#718096;--line:#e7edf3;--canvas:#f6f8fb;--white:#fff;--blue:#2864e8;--blue-soft:#edf3ff;--green:#15966b;--green-soft:#e8f8f1;--amber:#b87312;--amber-soft:#fff5e5;--shadow:0 8px 24px rgba(22,43,70,.06)}*{box-sizing:border-box}body{margin:0;background:var(--canvas);color:var(--ink);font:14px/1.5 system-ui,-apple-system,sans-serif}button{font:inherit;border:0;cursor:pointer}a{text-decoration:none;color:inherit}.shell{display:flex;min-height:100vh}.sidebar{width:238px;flex:none;background:var(--navy);color:#d8e1ec;padding:25px 15px;display:flex;flex-direction:column}.brand{display:flex;gap:11px;align-items:center;padding:0 12px 28px;color:#fff}.brand-mark{width:34px;height:34px;border-radius:10px;background:#4f8aff;display:grid;place-items:center;font-weight:800}.brand strong{font-size:16px}.brand small{display:block;color:#94aac4;font-size:10px}.nav-label{font-size:10px;text-transform:uppercase;letter-spacing:1.2px;color:#7188a3;padding:12px 13px 8px}.nav a{display:flex;align-items:center;gap:11px;padding:11px 13px;border-radius:8px;margin:2px 0;color:#b8c7d9}.nav a:hover,.nav a.active{background:#1e3856;color:#fff}.nav-icon{width:18px;text-align:center}.sidebar-bottom{margin-top:auto;border-top:1px solid #29415d;padding:16px 12px 0}.sync-dot{display:inline-block;width:7px;height:7px;border-radius:50%;background:#30c794;margin-right:6px}.sidebar-bottom small{color:#91a6bd;font-size:11px}.main{min-width:0;flex:1}.topbar{height:76px;background:var(--white);border-bottom:1px solid var(--line);display:flex;align-items:center;justify-content:space-between;padding:0 34px}.crumb{color:var(--muted);font-size:13px}.crumb strong{color:var(--ink)}.top-actions{display:flex;align-items:center;gap:18px}.profile{display:flex;align-items:center;gap:9px;border-left:1px solid var(--line);padding-left:18px}.avatar{width:33px;height:33px;border-radius:50%;display:grid;place-items:center;background:#e6efff;color:#2864e8;font-weight:700;font-size:12px}.profile small{display:block;color:var(--muted);font-size:11px}.content{max-width:1440px;margin:0 auto;padding:31px 34px 45px}.welcome{display:flex;justify-content:space-between;align-items:flex-start;gap:20px;margin-bottom:27px}.eyebrow{color:var(--blue);font-weight:700;font-size:11px;text-transform:uppercase;letter-spacing:1.1px}.welcome h1{font-size:26px;letter-spacing:-.7px;margin:5px 0}.welcome p{margin:0;color:var(--muted)}.date-select{background:#fff;border:1px solid var(--line);border-radius:7px;padding:10px 13px;color:#4a5b70}.metrics{display:grid;grid-template-columns:repeat(4,1fr);gap:16px;margin-bottom:22px}.card{background:#fff;border:1px solid var(--line);border-radius:10px;box-shadow:var(--shadow)}.metric{padding:18px 19px}.metric-head{display:flex;justify-content:space-between;color:var(--muted);font-size:12px;font-weight:600}.metric-value{font-size:25px;font-weight:700;margin:12px 0 7px}.subtle{font-size:11px;color:var(--muted)}.grid{display:grid;grid-template-columns:minmax(0,1.65fr) minmax(280px,.9fr);gap:20px;margin-bottom:20px}.panel-head{padding:19px 20px 14px;display:flex;justify-content:space-between;align-items:flex-start}.panel-title{margin:0;font-size:15px}.panel-sub{margin:3px 0 0;color:var(--muted);font-size:12px}.link{color:var(--blue);font-size:12px;font-weight:650}.chart-wrap{padding:7px 18px 17px}.chart{height:190px;width:100%;display:block}.chart-labels{display:flex;justify-content:space-between;color:#97a5b5;font-size:10px;padding:4px 6px 0}.empty{padding:24px 20px;color:var(--muted);font-size:13px}.table-panel{overflow:hidden}.table-scroll{overflow:auto}.data-table{width:100%;border-collapse:collapse;min-width:620px}.data-table th,.data-table td{text-align:left;padding:13px 20px;border-top:1px solid #eef2f5;white-space:nowrap}.data-table th{color:#8997a8;font-size:10px;text-transform:uppercase;letter-spacing:.7px;background:#fbfcfd}.data-table td{font-size:12px}.campaign{display:flex;align-items:center;gap:9px;font-weight:650}.platform{width:26px;height:26px;border-radius:7px;display:grid;place-items:center;font-size:10px;font-weight:800}.meta{background:#e9efff;color:#2764e5}.google{background:#e8f7ee;color:#1f9a63}.status{font-size:10px;border-radius:20px;padding:4px 8px;font-weight:700;color:var(--green);background:var(--green-soft)}.footer-note{color:#98a5b5;font-size:11px;margin-top:20px}.mobile-menu{display:none}.menu-backdrop{display:none}.sidebar-close{display:none}@media(max-width:900px){.metrics{grid-template-columns:repeat(2,1fr)}.grid{grid-template-columns:1fr}}@media(max-width:640px){.sidebar{display:flex;position:fixed;z-index:20;inset:0 auto 0 0;width:270px;transform:translateX(-105%);transition:transform .2s ease}.menu-open .sidebar{transform:translateX(0)}.menu-open .menu-backdrop{display:block;position:fixed;z-index:10;inset:0;background:#0a192d6b}.sidebar-close{display:block;position:absolute;right:13px;top:18px;background:transparent;color:#b8c7d9;font-size:22px}.mobile-menu{display:inline-block;background:transparent;color:var(--ink);font-size:20px}.topbar{height:64px;padding:0 16px}.content{padding:24px 15px}.welcome{display:block}.date-select{margin-top:16px;width:100%}.metrics{gap:10px}.metric{padding:14px}.metric-value{font-size:21px}}</style></head><body><div class="shell"><div class="menu-backdrop"></div><aside class="sidebar"><button class="sidebar-close" type="button">×</button><div class="brand"><?php if($logoUrl):?><img src="<?=$esc($logoUrl)?>" alt="Brand logo" style="width:34px;height:34px;border-radius:10px;object-fit:contain;background:#fff;padding:4px"><?php else:?><div class="brand-mark">SA</div><?php endif;?><div><strong><?=$brandName?></strong><small>ADPILOT</small></div></div><nav class="nav"><div class="nav-label">Workspace</div><a class="active" href="/">▦ Overview</a><a href="/page.php?view=campaigns">◉ Campaigns</a><a href="/page.php?view=creatives">◌ Creatives</a><a href="/page.php?view=insights">⌁ Insights</a><div class="nav-label">Control</div><a href="/page.php?view=approvals">✓ Approvals</a><a href="/page.php?view=automations">↗ Automations</a><a href="/page.php?view=activity">≡ Activity log</a><div class="nav-label">Settings</div><a href="/settings.php">⚙ Workspace settings</a></nav><div class="sidebar-bottom"><small><span class="sync-dot"></span><?=$esc($systemStatus)?></small><br><small><?=$hasLiveData?'Metrics available for selected range':'No completed sync in selected range'?></small></div></aside><main class="main"><header class="topbar"><div class="crumb"><button class="mobile-menu" type="button">☰</button> <strong>Overview</strong> <span> / Performance</span></div><div class="top-actions"><div class="profile"><div class="avatar">SA</div><div><strong>Admin</strong><small><a href="/logout.php">Sign out</a></small></div></div></div></header><section class="content"><div class="welcome"><div><div class="eyebrow">Live reporting workspace</div><h1>Campaign overview</h1><p>Showing <?= $esc($rangeLabel) ?><?= $hasLiveData?' from synced provider data.':'. Connect a provider and run the first sync.'?></p></div><div class="date-select"><?=$esc($rangeLabel)?> · <?=$esc($from)?> to <?=$esc($to)?></div></div><div class="metrics"><div class="card metric"><div class="metric-head"><span>Total spend</span><span>৳</span></div><div class="metric-value"><?=$currency?> <?=$spend?></div><div class="subtle">Synced provider data</div></div><div class="card metric"><div class="metric-head"><span>Conversions</span><span>↗</span></div><div class="metric-value"><?=$conversions?></div><div class="subtle">Synced provider data</div></div><div class="card metric"><div class="metric-head"><span>Average CPA</span><span>◎</span></div><div class="metric-value"><?=$currency?> <?=$cpa?></div><div class="subtle">Calculated from synced data</div></div><div class="card metric"><div class="metric-head"><span>Blended ROAS</span><span>✦</span></div><div class="metric-value"><?=$roas?>x</div><div class="subtle">Calculated from synced data</div></div></div><div class="grid"><section class="card"><div class="panel-head"><div><h2 class="panel-title">Spend & conversions</h2><p class="panel-sub">Daily performance from connected providers</p></div><a class="link" href="/page.php?view=insights">View report →</a></div><?php if($dailyTotals):?><div class="chart-wrap"><svg class="chart" viewBox="0 0 700 190" preserveAspectRatio="none" role="img" aria-label="Daily spend trend"><g stroke="#eef2f6" stroke-width="1"><path d="M0 25H700M0 73H700M0 121H700M0 169H700"/></g><?php $points=[]; $count=count($dailyTotals); foreach($dailyTotals as $i=>$row){$x=$count>1?($i/($count-1))*700:350;$y=170-((float)$row['spend']/max(1,$chartMax))*140;$points[]=round($x,1).','.round($y,1);} ?><polyline points="<?=implode(' ',$points)?>" fill="none" stroke="#2864e8" stroke-width="3"/></svg><div class="chart-labels"><span><?=$esc($dailyTotals[0]['insight_date'])?></span><span><?=$esc($dailyTotals[count($dailyTotals)-1]['insight_date'])?></span></div></div><?php else:?><div class="empty">No synced daily data yet. Add a provider in Settings, then run <code>php bin/sync.php</code>.</div><?php endif;?></section><section class="card"><div class="panel-head"><div><h2 class="panel-title">Connection status</h2><p class="panel-sub">Provider setup and sync state</p></div></div><div class="empty"><?php if($dbError):?>Database is unavailable. Check <code>.env</code> and <code>/health.php</code>.<?php elseif(!$hasLiveData):?>No live insight rows are available for this date range.<?php else:?>Live insight rows are available for this date range.<?php endif;?></div></section></div><section class="card table-panel"><div class="panel-head"><div><h2 class="panel-title">Top campaigns</h2><p class="panel-sub">Ranked by synced attributed revenue</p></div><a class="link" href="/page.php?view=campaigns">View all campaigns →</a></div><?php if($campaigns):?><div class="table-scroll"><table class="data-table"><thead><tr><th>Campaign</th><th>Platform</th><th>Spend</th><th>Conversions</th><th>CPA</th><th>ROAS</th></tr></thead><tbody><?php foreach($campaigns as $campaign): $campaignSpend=(float)$campaign['spend']; $campaignConversions=(float)$campaign['conversions']; $campaignRevenue=(float)$campaign['revenue']; $provider=(string)$campaign['provider']; ?><tr><td><div class="campaign"><span class="platform <?=$provider==='meta'?'meta':'google'?>"><?=$provider==='meta'?'M':'G'?></span><?=$esc((string)($campaign['entity_name']?:'Unnamed campaign'))?></div></td><td><?=$esc($provider==='meta'?'Meta Ads':'Google Ads')?></td><td><?=$currency?> <?=number_format($campaignSpend,2)?></td><td><?=number_format($campaignConversions,0)?></td><td><?=$currency?> <?=number_format($campaignConversions>0?$campaignSpend/$campaignConversions:0,2)?></td><td><?=number_format($campaignSpend>0?$campaignRevenue/$campaignSpend:0,2)?>x</td></tr><?php endforeach;?></tbody></table></div><?php else:?><div class="empty">No campaign data has been synced yet.</div><?php endif;?></section><div class="footer-note">Data source: connected provider accounts · <?= $demo && !$hasLiveData ? 'Demo preview data' : ($hasLiveData ? 'Live synced data' : 'No synced data') ?> · Environment: <?=$environment?></div></section></main></div><script>(()=>{const b=document.body,o=document.querySelector('.mobile-menu'),c=document.querySelector('.sidebar-close'),x=document.querySelector('.menu-backdrop');const set=v=>b.classList.toggle('menu-open',v);o?.addEventListener('click',()=>set(true));c?.addEventListener('click',()=>set(false));x?.addEventListener('click',()=>set(false));})();</script></body></html>
